import * as THREE from 'three';
import {sceneRendering} from '../scene-rendering.js';
import {makeSceneComponent} from '../scene-components.js';
import {create2DAsset} from '../two-d-assets.js';

export async function runTwoDSurfaceCase({renderer,scene,camera,groups,group,layers,pixel,expect}){
  let checks=0;const evidence=[],frames=[],check=(value,label)=>{checks++;if(!value)window.__hbSurfaceFailure={label,evidence,frame:renderer.domElement.toDataURL()};expect(value,label);},sources=new Map(),requests=[];
  const image=(name,width,height,paint)=>{const c=document.createElement('canvas');c.width=width;c.height=height;paint(c.getContext('2d'));sources.set(name,c.toDataURL());};
  image('color.png',64,32,c=>{c.fillStyle='#ffffff';c.fillRect(0,0,64,32);});
  image('normal.png',64,32,c=>{c.fillStyle='rgb(128,128,255)';c.fillRect(0,0,32,32);c.fillStyle='rgb(255,128,128)';c.fillRect(32,0,32,32);});
  image('y-normal.png',64,32,c=>{c.fillStyle='rgb(128,218,218)';c.fillRect(0,0,64,32);});
  image('alpha.png',3,1,c=>{const d=c.createImageData(3,1);d.data.set([255,0,0,0,255,0,0,128,255,0,0,255]);c.putImageData(d,0,0);});
  image('shadow.png',2,1,c=>{const d=c.createImageData(2,1);d.data.set([255,255,255,0,255,255,255,255]);c.putImageData(d,0,0);});
  const left={...create2DAsset('sprite','Left'),texture:'color.png',normalTexture:'normal.png',pixelsPerUnit:16,rect:[0,0,32,32],border:[8,8,8,8]},right={...left,name:'Right',rect:[32,0,32,32]},assets={'left.json':left,'right.json':right};
  const visuals=sceneRendering({read:async p=>{if(!assets[p])throw Error('unexpected asset '+p);return assets[p];},fileUrl:p=>{requests.push(p);if(!sources.has(p))throw Error('unexpected texture '+p);return sources.get(p);},loadModel:async()=>{throw Error('unexpected model');},current:id=>groups.find(g=>g.userData.objectId===id),all:()=>groups,error:e=>{throw Error(e);}});
  const object={id:'surface',kind:'sprite',components:[makeSceneComponent('SpriteRenderer',{sprite:'left.json',shading:'lit'})]},g=group(object.id),p=object.components[0].properties;
  const render=()=>{visuals.prepare2D(renderer,scene,camera,layers);renderer.render(scene,camera);return pixel();},shot=label=>{const c=document.createElement('canvas');c.width=c.height=64;c.getContext('2d').drawImage(renderer.domElement,0,0);frames.push({label,canvas:c});};
  const bright=v=>v[0]>170&&v[1]>170&&v[2]>170,red=v=>v[0]>200&&v[1]<30&&v[2]<30,black=v=>v.slice(0,3).every(n=>n<5);
  const light=new THREE.DirectionalLight(0xffffff,3);light.position.set(0,0,3);scene.add(light,light.target);
  try{
    await visuals.build(object,g);const flat=render();shot('Flat normal');const mat=g.userData.spriteMesh.material;
    check(bright(flat),'flat normal receives front light');check(mat.map.colorSpace===THREE.SRGBColorSpace&&mat.normalMap.colorSpace===THREE.NoColorSpace,'normal is linear data, color is sRGB');check(mat.map.offset.equals(mat.normalMap.offset)&&mat.map.repeat.equals(mat.normalMap.repeat),'color and normal share cropped atlas UV');
    const old=g.userData.spriteMesh,retired=[old.geometry,old.material,old.material.map,old.material.normalMap];let released=0;retired.forEach(r=>r.addEventListener('dispose',()=>released++));
    await visuals.spriteFrame(object,'right.json');const tilted=render();shot('Tilted normal');check(flat[0]>tilted[0]+100,'sprite frame changes both color and normal crop');check(released===4,'frame replacement releases geometry/material/color/normal clones');check(requests.filter(p=>p==='color.png').length===1&&requests.filter(p=>p==='normal.png').length===1,'flipbook reuses source color/normal atlases');
    p.normalStrength=0;await visuals.spriteFrame(object,'right.json');check(bright(render()),'zero normal strength restores flat lighting');p.normalStrength=1;
    for(const mode of ['sliced','tiled']){p.drawMode=mode;p.width=p.height=3;await visuals.spriteFrame(object,'left.json');check(bright(render())&&g.userData.spriteMesh.material.normalMap.repeat.equals(g.userData.spriteMesh.material.map.repeat),mode+' preserves normal atlas UV');}p.drawMode='simple';
    p.normalTexture='y-normal.png';light.position.set(0,3,3);await visuals.spriteFrame(object,'left.json');const positive=render();p.normalFlipY=true;await visuals.spriteFrame(object,'left.json');const negative=render();check(positive[0]>negative[0]+80,'normal Y inversion changes light direction');p.normalFlipY=false;
    p.shading='unlit';p.normalTexture='missing.png';await visuals.spriteFrame(object,'left.json');check(bright(render())&&!g.userData.spriteMesh.material.normalMap&&!requests.includes('missing.png'),'unlit skips normal texture loading');p.normalTexture='';
    light.removeFromParent();light.target.removeFromParent();p.texture='alpha.png';p.sprite='';p.width=p.height=2;
    renderer.setClearColor(0x00ff00,1);for(const mode of ['translucent','masked','opaque']){p.blendMode=mode;p.alphaCutoff=.6;await visuals.spriteFrame(object,'');render();const samples=[pixel(20,32),pixel(32,32),pixel(44,32)],m=g.userData.spriteMesh.material;shot(mode);evidence.push({kind:mode,pixels:samples,transparent:m.transparent,depthWrite:m.depthWrite});check(mode==='opaque'?black(samples[0])&&red(samples[1])&&red(samples[2]):samples[0][1]>200&&red(samples[2])&&(mode==='masked'?samples[1][1]>200:samples[1][0]>30&&samples[1][0]<240&&samples[1][1]>30),'surface alpha '+mode+' '+JSON.stringify(samples));check(m.transparent===(mode==='translucent')&&m.depthWrite===(mode!=='translucent'),'surface depth '+mode);}
    renderer.setClearColor(0,1);p.texture='shadow.png';p.width=p.height=1.2;p.blendMode='translucent';p.castShadow=true;p.alphaCutoff=.5;g.position.z=1;await visuals.spriteFrame(object,'');
    const caster=g.userData.spriteMesh;check(caster.castShadow&&!caster.receiveShadow&&caster.customDepthMaterial.alphaTest===.5&&caster.customDistanceMaterial.alphaTest===.5,'unlit alpha-cutout shadow caster uses directional and point materials');
    const receiver=group('receiver');await visuals.build({id:'receiver',kind:'sprite',components:[makeSceneComponent('SpriteRenderer',{width:4,height:4,shading:'lit',blendMode:'opaque',receiveShadow:true})]},receiver);
    const previousShadow={enabled:renderer.shadowMap.enabled,type:renderer.shadowMap.type};renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.BasicShadowMap;
    try{
      for(const kind of ['directional','point']){
        const l=kind==='directional'?new THREE.DirectionalLight(0xffffff,3):new THREE.PointLight(0xffffff,100,20);l.position.set(-3,0,4);l.castShadow=true;l.shadow.mapSize.set(128,128);l.shadow.bias=-.0001;l.shadow.camera.near=.1;l.shadow.camera.far=20;if(kind==='directional')Object.assign(l.shadow.camera,{left:-3,right:3,top:3,bottom:-3});scene.add(l);if(l.target)scene.add(l.target);
        try{render();const clear=pixel(43,32),shadow=pixel(50,32);shot(kind+' shadow');p.castShadow=false;await visuals.spriteFrame(object,'');render();const uncovered=pixel(50,32);evidence.push({kind,clear,shadow,uncovered});check(clear[0]>shadow[0]+60&&uncovered[0]>shadow[0]+60,kind+' alpha-cutout casts and receives GPU shadow '+JSON.stringify({clear,shadow,uncovered}));check(!g.userData.spriteMesh.customDepthMaterial&&!g.userData.spriteMesh.customDistanceMaterial,'disabled caster allocates no shadow materials');p.castShadow=true;await visuals.spriteFrame(object,'');}finally{l.removeFromParent();l.target?.removeFromParent();l.shadow.dispose();}
      }
    }finally{renderer.shadowMap.enabled=previousShadow.enabled;renderer.shadowMap.type=previousShadow.type;visuals.dispose(receiver);receiver.removeFromParent();groups.splice(groups.indexOf(receiver),1);}
    g.position.z=0;p.castShadow=false;p.texture='color.png';p.shading='lit';p.normalTexture='normal.png';p.blendMode='masked';p.maskInteraction='inside';await visuals.spriteFrame(object,'');scene.add(light,light.target);light.position.set(0,0,3);
    const mask=group('surface-mask');await visuals.build({id:'surface-mask',kind:'empty',components:[makeSceneComponent('SpriteMask',{texture:'shadow.png',width:2,height:2})]},mask);render();check(black(pixel(24,32)),'normal + masked + SpriteMask compiles and clips');visuals.dispose(mask);mask.removeFromParent();groups.splice(groups.indexOf(mask),1);
    visuals.dispose(g);g.removeFromParent();groups.splice(groups.indexOf(g),1);
    const map={...create2DAsset('tilemap','Normals'),tileset:'color.png',normalTexture:'normal.png',cellSize:[2,2]},tile=group('surface-tiles'),tileObject={id:'surface-tiles',kind:'tilemap',components:[makeSceneComponent('TilemapRenderer',{tilemap:'tiles.json',shading:'lit',blendMode:'masked',castShadow:true})]};map.layers[0].tiles=[{x:0,y:0,index:0}];assets['tiles.json']=map;tile.position.set(-1,1,0);await visuals.build(tileObject,tile);render();check(bright(pixel())&&tile.children[0].material.normalMap.colorSpace===THREE.NoColorSpace,'tile atlas uses matching linear normal map');check(tile.children[0].castShadow&&tile.children[0].customDistanceMaterial,'tile layers own shadow materials');
    const first=structuredClone(map),second=structuredClone(map);first.layers[0].id='old';second.layers[0].id='latest';await Promise.all([visuals.tilemapFrame({...tileObject,runtimeTilemapPath:'tiles.json'},first),visuals.tilemapFrame({...tileObject,runtimeTilemapPath:'tiles.json'},second)]);check(tile.children.filter(c=>c.userData.tilemap).length===1&&tile.children[0].userData.draw2dId==='tile:latest','latest async tile rebuild wins');
    visuals.dispose(tile);tile.removeFromParent();groups.splice(groups.indexOf(tile),1);
    const delayed=group('stale-sprite');let resume;assets['slow.json']=new Promise(r=>resume=r);const slowObject={id:'stale-sprite',kind:'sprite',components:[makeSceneComponent('SpriteRenderer',{sprite:'left.json',shading:'lit'})]};await visuals.build(slowObject,delayed);const slow=visuals.spriteFrame(slowObject,'slow.json'),latest=visuals.spriteFrame(slowObject,'right.json');await latest;resume(left);await slow;check(slowObject.currentSprite==='right.json'&&delayed.userData.spriteMesh.material.normalMap.offset.x===.5,'stale sprite load cannot replace latest normal frame');visuals.dispose(delayed);delayed.removeFromParent();groups.splice(groups.indexOf(delayed),1);
    check(renderer.info.programs.every(p=>p.diagnostics?.runnable!==false),'surface and shadow shader compilation');
    const proof=document.createElement('canvas');proof.width=3*128;proof.height=Math.ceil(frames.length/3)*150;const c=proof.getContext('2d');c.fillStyle='#202226';c.fillRect(0,0,proof.width,proof.height);frames.forEach((f,i)=>{const x=i%3*128,y=Math.floor(i/3)*150;c.drawImage(f.canvas,x,y,128,128);c.fillStyle='#eeeeee';c.font='12px sans-serif';c.fillText(f.label,x+4,y+144);});return {checks,evidence,image:proof.toDataURL()};
  }finally{for(const owned of groups.splice(0)){visuals.dispose(owned);owned.removeFromParent();}visuals.dispose(g);visuals.dispose2D();g.removeFromParent();light.removeFromParent();light.target.removeFromParent();}
}
